-- Giftwise — tables for phpMyAdmin (prefix gw_). Generated by tools/build-sql.php. Alternative to install-db.php.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS `gw_meta` (
  `k` VARCHAR(40) NOT NULL PRIMARY KEY,
  `v` VARCHAR(255) NOT NULL
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_users` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(80) NOT NULL,
  `email` VARCHAR(190) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL DEFAULT '',
  `google_sub` VARCHAR(64) NULL,
  `invite_code` CHAR(10) NOT NULL,
  `lang` CHAR(2) NOT NULL DEFAULT 'en',
  `status` ENUM('active','disabled') NOT NULL DEFAULT 'active',
  `created_at` DATETIME NOT NULL,
  `last_login_at` DATETIME NULL,
  `last_seen_at` DATETIME NULL,
  UNIQUE KEY `uq_email` (`email`),
  UNIQUE KEY `uq_google` (`google_sub`),
  UNIQUE KEY `uq_invite` (`invite_code`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_auth_tokens` (
  `token_hash` CHAR(64) NOT NULL PRIMARY KEY,
  `user_id` INT UNSIGNED NOT NULL,
  `csrf_token` CHAR(48) NOT NULL,
  `user_agent` VARCHAR(255) NOT NULL DEFAULT '',
  `ip` VARCHAR(45) NOT NULL DEFAULT '',
  `created_at` DATETIME NOT NULL,
  `last_seen_at` DATETIME NOT NULL,
  `expires_at` DATETIME NOT NULL,
  KEY `ix_user` (`user_id`),
  CONSTRAINT `fk_gw_tok_user` FOREIGN KEY (`user_id`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_attempts` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `kind` VARCHAR(20) NOT NULL,
  `ip` VARCHAR(45) NOT NULL,
  `created_at` DATETIME NOT NULL,
  KEY `ix_kind_ip` (`kind`, `ip`, `created_at`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_friendships` (
  `user_a` INT UNSIGNED NOT NULL,
  `user_b` INT UNSIGNED NOT NULL,
  `status` ENUM('pending','accepted') NOT NULL DEFAULT 'pending',
  `requested_by` INT UNSIGNED NOT NULL,
  `created_at` DATETIME NOT NULL,
  `accepted_at` DATETIME NULL,
  PRIMARY KEY (`user_a`, `user_b`),
  KEY `ix_b` (`user_b`),
  CONSTRAINT `fk_gw_fr_a` FOREIGN KEY (`user_a`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gw_fr_b` FOREIGN KEY (`user_b`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_lists` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `owner_id` INT UNSIGNED NOT NULL,
  `title` VARCHAR(80) NOT NULL,
  `occasion` VARCHAR(20) NOT NULL DEFAULT 'other',
  `event_date` DATE NULL,
  `description` VARCHAR(500) NOT NULL DEFAULT '',
  `visibility` ENUM('friends','selected') NOT NULL DEFAULT 'friends',
  `archived` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  KEY `ix_owner` (`owner_id`),
  CONSTRAINT `fk_gw_list_owner` FOREIGN KEY (`owner_id`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_list_viewers` (
  `list_id` INT UNSIGNED NOT NULL,
  `user_id` INT UNSIGNED NOT NULL,
  PRIMARY KEY (`list_id`, `user_id`),
  CONSTRAINT `fk_gw_lv_list` FOREIGN KEY (`list_id`) REFERENCES `gw_lists` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gw_lv_user` FOREIGN KEY (`user_id`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_items` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `list_id` INT UNSIGNED NOT NULL,
  `title` VARCHAR(160) NOT NULL,
  `url` VARCHAR(2000) NOT NULL DEFAULT '',
  `image_url` VARCHAR(2000) NOT NULL DEFAULT '',
  `price` DECIMAL(10,2) NULL,
  `currency` CHAR(3) NOT NULL DEFAULT 'EUR',
  `notes` VARCHAR(1000) NOT NULL DEFAULT '',
  `priority` TINYINT NOT NULL DEFAULT 0,
  `quantity` SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  `sort` INT NOT NULL DEFAULT 0,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  KEY `ix_list` (`list_id`),
  CONSTRAINT `fk_gw_item_list` FOREIGN KEY (`list_id`) REFERENCES `gw_lists` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_claims` (
  `item_id` INT UNSIGNED NOT NULL,
  `user_id` INT UNSIGNED NOT NULL,
  `status` ENUM('considering','taken') NOT NULL,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`item_id`, `user_id`),
  KEY `ix_user` (`user_id`),
  CONSTRAINT `fk_gw_cl_item` FOREIGN KEY (`item_id`) REFERENCES `gw_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gw_cl_user` FOREIGN KEY (`user_id`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `gw_comments` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `list_id` INT UNSIGNED NOT NULL,
  `item_id` INT UNSIGNED NULL,
  `user_id` INT UNSIGNED NOT NULL,
  `body` VARCHAR(1000) NOT NULL,
  `created_at` DATETIME NOT NULL,
  KEY `ix_list` (`list_id`, `created_at`),
  KEY `ix_item` (`item_id`),
  CONSTRAINT `fk_gw_cm_list` FOREIGN KEY (`list_id`) REFERENCES `gw_lists` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gw_cm_item` FOREIGN KEY (`item_id`) REFERENCES `gw_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_gw_cm_user` FOREIGN KEY (`user_id`) REFERENCES `gw_users` (`id`) ON DELETE CASCADE
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `gw_meta` (k, v) VALUES ('schema_version', '1') ON DUPLICATE KEY UPDATE v = VALUES(v);
